"""JSON transport for the release planner."""
import json
import sys

from planner import plan


def main():
    try:
        request = json.load(sys.stdin)
    except (ValueError, TypeError):
        result = {"status": "error", "error": "invalid-json", "actions": [], "units": 0}
    else:
        result = plan(request)
    print(json.dumps(result, separators=(",", ":")))


if __name__ == "__main__":
    main()

journal.py.text:
"""Normalize release records at the input boundary.

This module owns *identity*: it decides when two records are the same change and
when the same change ID carries contradicting payloads. The planner may rely on
`read_changes` returning one record per ID with `depends_on` already reduced to a
sorted tuple.
"""


class JournalError(ValueError):
    pass


def _invalid():
    return JournalError("invalid-change")


def _dependency_ids(depends_on):
    if depends_on is None:
        return frozenset()
    if not isinstance(depends_on, list):
        raise _invalid()
    for dep in depends_on:
        if not isinstance(dep, str) or not dep:
            raise _invalid()
    # Dependencies are a *set*: order and repetition carry no meaning, so
    # ["a","b"], ["b","a","a"] and ["a","b"] all identify the same record and
    # collapse during replay. Sorted before comparison for the same reason.
    return frozenset(depends_on)


def read_applied(records):
    if records is None:
        return ()
    if not isinstance(records, list):
        raise _invalid()
    for item in records:
        if not isinstance(item, str) or not item:
            raise _invalid()
    return tuple(records)


def read_changes(records):
    if not isinstance(records, list):
        raise _invalid()
    changes = {}
    for row in records:
        if (not isinstance(row, dict) or not isinstance(row.get("id"), str) or not row["id"]
                or not isinstance(row.get("component"), str) or not row["component"]
                or type(row.get("units")) is not int or row["units"] < 1):
            raise _invalid()
        deps = _dependency_ids(row.get("depends_on"))
        record = {"id": row["id"], "component": row["component"], "units": row["units"],
                  "depends_on": tuple(sorted(deps))}
        seen = changes.get(row["id"])
        if seen is None:
            changes[row["id"]] = record
