"""Compose policy and journal data into a plan."""
import heapq

from journal import JournalError, check_references, read_applied, read_changes
from policy import PolicyError, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


class GraphError(ValueError):
    pass


def _topological_order(changes):
    """Full deterministic order: edges point dependency -> dependent.

    Among currently eligible changes (all dependencies already emitted) the
    lexicographically smallest ID goes first, which makes the order a pure
    function of the deduplicated record set - not of input order.
    """
    deps = {row["id"]: set(row["depends_on"]) for row in changes}
    dependents = {row["id"]: [] for row in changes}
    for row in changes:
        for dep in row["depends_on"]:
            dependents[dep].append(row["id"])
    remaining = {change_id: len(deps[change_id]) for change_id in deps}
    ready = [change_id for change_id, count in remaining.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        change_id = heapq.heappop(ready)
        order.append(change_id)
        for child in dependents[change_id]:
            remaining[child] -= 1
            if remaining[child] == 0:
                heapq.heappush(ready, child)
    # Fewer emitted than known IDs means a cycle somewhere in the graph; we fail
    # the whole request (no partial actions) rather than emit the acyclic part.
    if len(order) != len(deps):
        raise GraphError("dependency-cycle")
    return order


