        changes = read_changes(request.get("changes"))
        check_references(changes, applied)
        order = _topological_order(changes)
    except (PolicyError, JournalError, GraphError) as exc:
        return failure(str(exc))
    if request.get("action") == "rollback":
        # Undo in reverse of the full order, restricted to what is on record.
        # The budget was validated by policy but deliberately does not cap a
        # rollback: refusing to unwind a release over quota would strand it.
        actions = [change_id for change_id in reversed(order) if change_id in applied]
    else:
        # Replay first: already-applied changes neither reappear nor consume
        # budget, yet they still satisfy their dependents (handled by the order).
        actions = [change_id for change_id in order if change_id not in applied]
        units = _units_of(changes, actions)
