"""Normalize release records at the input boundary.

This module owns *identity*: it decides when two records are the same change and
when the same change ID carries contradicting payloads. The planner may rely on
`read_changes` returning one record per ID with `depends_on` already reduced to a
sorted tuple.
"""


class JournalError(ValueError):
    pass


def _invalid():
    return JournalError("invalid-change")


def _dependency_ids(depends_on):
    if depends_on is None:
        return frozenset()
    if not isinstance(depends_on, list):
        raise _invalid()
    for dep in depends_on:
        if not isinstance(dep, str) or not dep:
            raise _invalid()
    # Dependencies are a *set*: order and repetition carry no meaning, so
    # ["a","b"], ["b","a","a"] and ["a","b"] all identify the same record and
    # collapse during replay. Sorted before comparison for the same reason.
    return frozenset(depends_on)


def read_applied(records):
    if records is None:
        return ()
    if not isinstance(records, list):
        raise _invalid()
    for item in records:
        if not isinstance(item, str) or not item:
            raise _invalid()
    return tuple(records)


def read_retain(records):
    if records is None:
        return ()
    if not isinstance(records, list):
        raise JournalError("invalid-retain")
    for item in records:
        if not isinstance(item, str) or not item:
            raise JournalError("invalid-retain")
    return tuple(records)


def check_retain(retain, applied):
    """A retained ID must be applied; retaining anything else is a contradiction.

    Checked here with the rest of the journal checks so a bad retain list is
    `invalid-retain` regardless of whether the ID is unknown to `changes` at
    all. `applied` is the persisted journal the caller supplied - an ID that
    was never applied cannot "remain" anything, and a malformed list is
    refused rather than interpreted, because guessing which entries to keep
    would silently drop changes the caller asked to preserve.
    """
    for item in retain:
        if item not in applied:
            raise JournalError("invalid-retain")


def read_changes(records):
    if not isinstance(records, list):
        raise _invalid()
    changes = {}
    for row in records:
        if (not isinstance(row, dict) or not isinstance(row.get("id"), str) or not row["id"]
                or not isinstance(row.get("component"), str) or not row["component"]
                or type(row.get("units")) is not int or row["units"] < 1):
            raise _invalid()
        deps = _dependency_ids(row.get("depends_on"))
        record = {"id": row["id"], "component": row["component"], "units": row["units"],
                  "depends_on": tuple(sorted(deps))}
        seen = changes.get(row["id"])
        if seen is None:
            changes[row["id"]] = record
            continue
        # Replay identity: equal id/component/units/dependency-set is the *same*
        # change and collapses to one (accounting happens once, later). Any
        # difference is a contradiction between two journals, so fail closed
        # instead of silently picking one - a wrong pick would mis-price the plan.
        if seen != record:
            raise JournalError("conflicting-change")
    return list(changes.values())


def check_references(changes, applied):
    """Every graph edge and every applied ID must name a known change.

    Both are checked here (input boundary) rather than in the planner so a bad
    reference is reported as `unknown-dependency` regardless of action, and no
    graph is ever built from dangling edges.
    """
    known = {row["id"] for row in changes}
    for row in changes:
        for dep in row["depends_on"]:
            if dep not in known:
                raise JournalError("unknown-dependency")
    # `applied` is the caller's persisted journal. An ID we have never seen means
    # the caller's release history and this request disagree; refusing is safer
    # than pretending the change is pending.
    for item in applied:
        if item not in known:
            raise JournalError("unknown-dependency")

