"""Compose policy and journal data into a plan."""
import heapq

from journal import (JournalError, check_references, check_retain, read_applied,
                     read_changes, read_retain)
from policy import PolicyError, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


class GraphError(ValueError):
    pass


def _topological_order(changes):
    """Full deterministic order: edges point dependency -> dependent.

    Among currently eligible changes (all dependencies already emitted) the
    lexicographically smallest ID goes first, which makes the order a pure
    function of the deduplicated record set - not of input order.
    """
    deps = {row["id"]: set(row["depends_on"]) for row in changes}
    dependents = {row["id"]: [] for row in changes}
    for row in changes:
        for dep in row["depends_on"]:
            dependents[dep].append(row["id"])
    remaining = {change_id: len(deps[change_id]) for change_id in deps}
    ready = [change_id for change_id, count in remaining.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        change_id = heapq.heappop(ready)
        order.append(change_id)
        for child in dependents[change_id]:
            remaining[child] -= 1
            if remaining[child] == 0:
                heapq.heappush(ready, child)
    # Fewer emitted than known IDs means a cycle somewhere in the graph; we fail
    # the whole request (no partial actions) rather than emit the acyclic part.
    if len(order) != len(deps):
        raise GraphError("dependency-cycle")
    return order


def _retained_ids(changes, applied, retain):
    """Retained changes plus the applied dependencies they transitively need.

    `retain` is a keep-set, not an operation: a preserved change is useless if
    something it depends on is torn down underneath it, so the closure keeps
    every applied ancestor too. Only applied IDs enter the closure (retain was
    already checked against `applied`), and the result is therefore a subset of
    `applied` - it only ever removes work from the rollback.
    """
    deps = {row["id"]: row["depends_on"] for row in changes}
    keep = set()
    pending = [change_id for change_id in retain if change_id not in keep]
    while pending:
        change_id = pending.pop()
        if change_id in keep:
            continue
        keep.add(change_id)
        for dep in deps[change_id]:
            if dep in applied and dep not in keep:
                pending.append(dep)
    return keep


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        # Policy first: environment/action/budget errors outrank record errors,
        # and the production freeze outranks everything, including a malformed
        # graph. `budget` is already the effective (capped) staging budget.
        budget = limit_for(request)
        applied = set(read_applied(request.get("applied")))
        changes = read_changes(request.get("changes"))
        check_references(changes, applied)
        # Retain is validated before the graph is built: a malformed or
        # non-applied retain list is a caller contradiction and must not reach
        # ordering, which would otherwise have to run first and could fail as
        # a cycle/budget error instead.
        retain = read_retain(request.get("retain"))
        check_retain(retain, applied)
        order = _topological_order(changes)
    except (PolicyError, JournalError, GraphError) as exc:
        return failure(str(exc))
    if request.get("action") == "rollback":
        # Undo in reverse of the full order, restricted to what is on record.
        # The budget was validated by policy but deliberately does not cap a
        # rollback: refusing to unwind a release over quota would strand it.
        keep = _retained_ids(changes, applied, retain)
        actions = [change_id for change_id in reversed(order)
                   if change_id in applied and change_id not in keep]
    else:
        # Replay first: already-applied changes neither reappear nor consume
        # budget, yet they still satisfy their dependents (handled by the order).
        actions = [change_id for change_id in order if change_id not in applied]
        units = _units_of(changes, actions)
        if units > budget:
            return failure("budget-exceeded")
    return {"status": "ok", "actions": actions, "units": _units_of(changes, actions)}


def _units_of(changes, actions):
    emitted = set(actions)
    return sum(row["units"] for row in changes if row["id"] in emitted)

