"""Compose policy and journal data into a plan."""
import heapq

from journal import JournalError, collapse, read_applied, read_changes
from policy import PolicyError, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def _check_graph(ids, deps_by_id, applied):
    """Reject dangling dependency targets and unknown applied IDs.

    This runs before cycle detection so an input that is both dangling and cyclic
    reports `unknown-dependency`: a missing node cannot be ordered at all.
    `applied` entries are checked against the change set for the same reason. A
    self-dependency is not special-cased here; the orderer reports it as a cycle.
    """
    for change_id in ids:
        for dep in deps_by_id[change_id]:
            if dep not in deps_by_id:
                return False
    for change_id in applied:
        if change_id not in deps_by_id:
            return False
    return True


def _topological_order(ids, deps_by_id):
    """Return the full deterministic topological order, or None when a cycle exists.

    Edge direction: `deps_by_id[x]` are the things x depends on, i.e. x -> dep.
    We count, per change, how many of its dependencies are still unordered and
    release a change once that count reaches zero, so a dependency is always
    emitted before its dependents. This is the rollout order; rollback is exactly
    its reverse.

    Tie-breaking uses a heap over the currently eligible IDs, which is exactly
    "lexicographic among currently eligible" rather than a global pre-sort: a
    lexicographically later ID can be emitted before an earlier one that is still
    blocked by its dependencies.

    `applied` deliberately does NOT participate here. The order must be a property
    of the graph alone, otherwise the same release journal could produce a
    different rollout and rollback order depending on what happens to be applied.
    Both actions slice this single full order instead.
    """
    pending = {change_id: len(deps_by_id[change_id]) for change_id in ids}
    dependents = {change_id: [] for change_id in ids}
    for change_id in ids:
        for dep in deps_by_id[change_id]:
            dependents[dep].append(change_id)

    eligible = [change_id for change_id in ids if pending[change_id] == 0]
    heapq.heapify(eligible)
    order = []
    while eligible:
        change_id = heapq.heappop(eligible)
        order.append(change_id)
        for dependent in dependents[change_id]:
            pending[dependent] -= 1
            if pending[dependent] == 0:
                heapq.heappush(eligible, dependent)

    if len(order) != len(ids):
        # Some node never became eligible: it sits in, or downstream of, a cycle.
        # Report the cycle instead of a partial order, so no partial actions leak.
        return None
    return order


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        budget = limit_for(request)
        # read_changes keeps input order; collapse resolves replay identity before
        # any accounting, so duplicated records never double-count units.
        changes = collapse(read_changes(request.get("changes")))
        applied = read_applied(request.get("applied", []))
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    by_id = {row["id"]: row for row in changes}
