        applied = read_applied(request.get("applied", []))
        retain = read_retain(request.get("retain", []))
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    by_id = {row["id"]: row for row in changes}
    # Sorted IDs keep the heap tie-break lexicographic regardless of input order.
    ids = sorted(by_id)
    deps_by_id = {change_id: by_id[change_id]["depends_on"] for change_id in ids}

    if not _check_graph(ids, deps_by_id, applied):
        return failure("unknown-dependency")
    order = _topological_order(ids, deps_by_id)
    if order is None:
        return failure("dependency-cycle")

    if request["action"] == "rollback":
        # Rollback emits only applied changes, taking the reverse of the full order
        # so dependents are removed before the things they depend on. The budget
        # field was validated above but deliberately does not cap rollback: a
        # depleted budget must never leave the system un-reversible.
        #
        # G2 retention only filters this list; it never reorders it, so retained
        # changes simply drop out and everything else keeps the reverse order.
        retained = _retained_ids(retain, deps_by_id, applied)
        if retained is None:
            return failure("invalid-retain")
        actions = [change_id for change_id in reversed(order)
                   if change_id in applied and change_id not in retained]
    else:
        # Plan emits only unapplied changes. Applied entries already satisfy their
        # dependents (they are fixed points of the order) and consume no new budget.
        # `retain` is a rollback-only field and is ignored here, not validated.
        actions = [change_id for change_id in order if change_id not in applied]
        units = sum(by_id[change_id]["units"] for change_id in actions)
        if units > budget:
            # Checked against emitted units, after replay and dedup, so deduped
            # duplicates or already-applied work cannot inflate the budget demand.
            # `budget` is already the G2 staging cap, so a large request cannot
            # widen this gate.
            return failure("budget-exceeded")

    # No budget gate applies to rollback, so summing here is right for both actions
    # and keeps `units` equal to the units of the emitted actions.
    units = sum(by_id[change_id]["units"] for change_id in actions)
    return {"status": "ok", "actions": actions, "units": units}

